def joint(model,source,comp,name,root,out,cfg,edges,valley,counter):
    with np.load(input_root(cfg)/'JOINT8_INPUTS_PRIVATE.npz',allow_pickle=False)as z:a={k:z[k].copy()for k in z.files}
    parent=a['source_parent_index'];pick=parent.reshape(128,8)[:,0]
    assert np.all(parent.reshape(128,8)==pick[:,None])
    pre,original,innovation=infer(model,a['source_waveforms_V'],a['z'],a['white'],a['style'],cfg['generation_chunk']);detail=model.details
    post,ad=adc(pre);counter['repeat_noise_rows']+=len(post);f=ev.features(canonical(post))
    from flow_core import bins
    sb=bins(source[pick],edges);p=f['features']['PSD'].reshape(128,8);q=f['features']['Qtotal_mVns'].reshape(128,8);valid=f['valid'].reshape(128,8)
    # The last component includes the final float32 cast. It is an algebraic
    # decomposition of saved preADC output, not physical signal/electronics.
    original=original.astype('f8');learned=pre.astype('f8')-original-innovation
